package com.xenris.liquidwarsos;
import static com.xenris.liquidwarsos.World170ProbeTest.*;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.lifecycle.Lifecycle;
import com.xenris.liquidwarsos.activities.*;import com.xenris.liquidwarsos.cloud.*;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;
@RunWith(AndroidJUnit4.class)
public class Large171ProbeTest {
 static final short[] IDLE={-2,-1,-1,-1,-1};
 static void idle(){for(int t=0;t<6;t++)NativeInterface.setPlayerPosition(t,IDLE,IDLE);}
 static void apply(ActivityScenario<GameActivity> scene)throws Exception{short[][] xy=targets(scene);NativeInterface.setPlayerPosition(StaticBits.team,xy[0],xy[1]);}
 static void readyGL(MyGLSurfaceView gl,int tiles)throws Exception{long until=SystemClock.uptimeMillis()+7000;while((NativeInterface.sceneInfo()[6]!=tiles||gl.framesDrawn()<2)&&SystemClock.uptimeMillis()<until)SystemClock.sleep(30);Assert.assertEquals(tiles,NativeInterface.sceneInfo()[6]);SystemClock.sleep(180);}
 static MiniMapLayout mini(ItemOverlay h,boolean teleport){WorldCamera c=((MyGLSurfaceView)((View)h.getParent()).findViewById(R.id.mySurfaceView)).camera;return new MiniMapLayout(h.getWidth(),h.getHeight(),context().getResources().getDisplayMetrics().density,c.width,c.height,teleport);}
 static void miniTap(ItemOverlay h,Rect bounds,int x,int y,boolean teleport){MiniMapLayout m=mini(h,teleport);WorldCamera c=((MyGLSurfaceView)((View)h.getParent()).findViewById(R.id.mySurfaceView)).camera;tap(bounds.left+m.left+(x+.5f)*m.width/c.width,bounds.top+m.top+(c.height-.5f-y)*m.height/c.height);}
 @Test public void healthAndDirectMinimapTeleport()throws Exception{
  Intent intent=prepare(1,116,100,true,false);StaticBits.team=1;
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(intent)){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] h={null};Rect bounds=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);h[0]=a.findViewById(R.id.item_overlay);h[0].getGlobalVisibleRect(bounds);});readyGL(gl[0],0);idle();
   for(int n=0;n<2000&&NativeInterface.itemSnapshot()[2]==0;n++)NativeInterface.stepDots();int[] wave=NativeInterface.itemSnapshot();int slot=-1;for(int k=0;k<SnapshotItems.slots(wave);k++)if(wave[SnapshotItems.offset(wave,k)]==3)slot=k;Assert.assertTrue("natural teleport fixture",slot>=0);int at=SnapshotItems.offset(wave,slot),x=wave[at+1],y=wave[at+2];short[] tx=IDLE.clone(),ty=IDLE.clone();tx[0]=(short)x;ty[0]=(short)y;NativeInterface.setPlayerPosition(1,tx,ty);
   int[] contact=null;for(int n=0;n<1400;n++){NativeInterface.stepDots();int[] now=NativeInterface.itemSnapshot();if(SnapshotItems.hp(now,slot)<1200){contact=now;break;}}
   Assert.assertNotNull("contact reached",contact);Assert.assertEquals(3,contact[SnapshotItems.offset(contact,slot)]);Assert.assertEquals(0,contact[157]);Assert.assertTrue(SnapshotItems.hp(contact,slot)>=1196);SystemClock.sleep(150);picture("world171-item-first-contact.jpg");
   for(int n=0;n<150;n++)NativeInterface.stepDots();int[] middle=NativeInterface.itemSnapshot();Assert.assertEquals(3,middle[SnapshotItems.offset(middle,slot)]);Assert.assertTrue(SnapshotItems.hp(middle,slot)>0&&SnapshotItems.hp(middle,slot)<1200);SystemClock.sleep(160);picture("world171-item-half-hp.jpg");int[] held=NativeInterface.itemSnapshot();SystemClock.sleep(180);Assert.assertArrayEquals("paused HP does not tick",held,NativeInterface.itemSnapshot());
   for(int n=0;n<1500&&NativeInterface.itemSnapshot()[157]!=3;n++)NativeInterface.stepDots();Assert.assertEquals(3,NativeInterface.itemSnapshot()[157]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("world171-minimap-teleport-ready.jpg");Assert.assertFalse((Boolean)get(h[0],"aiming"));
   byte[] wall=NativeInterface.modelTerrain();int wx=-1,wy=-1,fx=-1,fy=-1;for(int yy=20;yy<460;yy+=8)for(int xx=25;xx<775;xx+=8){boolean rock=true,floor=true;for(int dy=-3;dy<=3;dy++)for(int dx=-3;dx<=3;dx++){rock&=wall[(yy+dy)*800+xx+dx]!=0;floor&=wall[(yy+dy)*800+xx+dx]==0;}if(rock&&wx<0){wx=xx;wy=yy;}if(floor&&xx>450&&fx<0){fx=xx;fy=yy;}}Assert.assertTrue(wx>=0&&fx>=0);
   miniTap(h[0],bounds,wx,wy,true);apply(scene);NativeInterface.stepDots();Assert.assertEquals("wall keeps teleport",3,NativeInterface.itemSnapshot()[157]);SystemClock.sleep(180);picture("world171-minimap-wall-rejected.jpg");
   int armyBefore=NativeInterface.itemSnapshot()[14];miniTap(h[0],bounds,fx,fy,true);short[][] selected=targets(scene);Assert.assertEquals(-3,selected[0][4]);Assert.assertEquals(fx,selected[0][3]);Assert.assertEquals(fy,selected[1][3]);apply(scene);NativeInterface.stepDots();int[] done=NativeInterface.itemSnapshot();Assert.assertEquals(0,done[157]);Assert.assertEquals(armyBefore,done[11]);NativeInterface.setPlayerPosition(1,IDLE,IDLE);SystemClock.sleep(180);picture("world171-minimap-teleported.jpg");
   long before=gl[0].framesDrawn();scene.onActivity(a->{gl[0].onPause();gl[0].onResume();});long deadline=SystemClock.uptimeMillis()+5000;while(gl[0].framesDrawn()<=before&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(30);Assert.assertTrue(gl[0].framesDrawn()>before);Assert.assertArrayEquals(done,NativeInterface.itemSnapshot());
   write("world171-health-teleport.json",new JSONObject().put("status","PASS").put("natural_pickup",true).put("first_contact_hp",SnapshotItems.hp(contact,slot)).put("middle_hp",SnapshotItems.hp(middle,slot)).put("paused_hp_stable",true).put("no_bottom_card_required",true).put("wall_rejected_retained",true).put("selected_xy",new JSONArray().put(fx).put(fy)).put("teleported",armyBefore).put("egl_stable",true).put("models",0).put("controlled_native_steps",true));
  }
 }
 @Test public void eightTilesControlsAndReplay()throws Exception{
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(prepare(52,17152,1000,true,false))){
   frozen(scene);MyGLSurfaceView[] gl={null};ItemOverlay[] h={null};Rect bounds=new Rect();scene.onActivity(a->{gl[0]=a.findViewById(R.id.mySurfaceView);h[0]=a.findViewById(R.id.item_overlay);h[0].getGlobalVisibleRect(bounds);});readyGL(gl[0],8);int[] info=NativeInterface.sceneInfo();Assert.assertEquals(3200,info[0]);Assert.assertEquals(960,info[1]);Assert.assertEquals(3072000,NativeInterface.modelTerrain().length);Assert.assertTrue(info[7]>=1600&&info[8]>=960);picture("world171-large-near.jpg");
   int[] dots=NativeInterface.modelSnapshot();byte[] walls=NativeInterface.modelTerrain();for(int i=217;i<dots.length;i++){int x=dots[i]&4095,y=dots[i]>>>12&1023;Assert.assertEquals(0,walls[y*3200+x]);}Assert.assertEquals(6000,dots[216]);
   miniTap(h[0],bounds,2900,740,false);SystemClock.sleep(150);Assert.assertFalse(gl[0].camera.following);Assert.assertTrue(gl[0].camera.left>2000);picture("world171-large-east.jpg");
   float dp=context().getResources().getDisplayMetrics().density;long down=SystemClock.uptimeMillis();touch(down,0,bounds.left+76*dp,bounds.bottom-66*dp);touch(down,2,bounds.left+110*dp,bounds.bottom-80*dp);SystemClock.sleep(220);touch(down,1,bounds.left+110*dp,bounds.bottom-80*dp);short[][] released=targets(scene);Assert.assertTrue(released[0][0]>=0&&released[0][0]<3200);SystemClock.sleep(120);Assert.assertArrayEquals(released[0],targets(scene)[0]);
   scene.onActivity(a->{gl[0].camera.overview=true;gl[0].camera.focus(1600,480);gl[0].applyCamera();});SystemClock.sleep(180);picture("world171-large-full.jpg");long frames=gl[0].framesDrawn();int[] paused=NativeInterface.itemSnapshot();scene.onActivity(a->{gl[0].onPause();gl[0].onResume();});long restored=SystemClock.uptimeMillis()+7000;while(gl[0].framesDrawn()<=frames&&SystemClock.uptimeMillis()<restored)SystemClock.sleep(30);readyGL(gl[0],8);Assert.assertTrue("new rendered frame after EGL rebuild",gl[0].framesDrawn()>frames);Assert.assertArrayEquals(paused,NativeInterface.itemSnapshot());picture("world171-large-resumed.jpg");
   scene.onActivity(a->gl[0].onPause());NativeInterface.destroyGame();JSONArray rows=new JSONArray();for(int seed=0;seed<2;seed++){long[] before=null;for(int pass=0;pass<2;pass++){NativeInterface.createGame(2,52,17100+seed,100);NativeInterface.configureAlliances(AllianceRules.solo());long[] hs=new long[22];int at=0;for(int step=0;step<=1400;step++){if(step%64==0)hs[at++]=NativeInterface.stateHash();if(step==1400)break;if(step%10==0)for(int t=0;t<6;t++){short[] xs={(short)(20+(step*13+t*411)%3160),-1,-1,-1,-1},ys={(short)(8+(step*7+t*131)%944),-1,-1,-1,-1};NativeInterface.setPlayerPosition(t,xs,ys);}NativeInterface.stepDots();}if(pass==0)before=hs;else Assert.assertArrayEquals(before,hs);NativeInterface.destroyGame();}rows.put(new JSONObject().put("seed",17100+seed).put("checkpoints",22));}NativeInterface.createGame(2,52,17152,1000);
   write("world171-large-controls.json",new JSONObject().put("status","PASS").put("width",3200).put("height",960).put("textures",8).put("particles",6000).put("minimap_pan",true).put("fixed_sticks",true).put("egl_resume",true).put("native_hash_replay",rows).put("models",0).put("real_touch",true));
  }
 }
 @Test public void ordinaryLargeMapWorkerAndModeSetup()throws Exception{
  try(ActivityScenario<SinglePlayerGameSetupActivity> scene=ActivityScenario.launch(new Intent(context(),SinglePlayerGameSetupActivity.class).putExtra("largeMode",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))){scene.onActivity(a->{Assert.assertEquals(52,StaticBits.map);Assert.assertEquals(1,((Spinner)a.findViewById(R.id.map_spinner)).getCount());Assert.assertEquals(a.getString(R.string.large_map_mode),((TextView)a.findViewById(R.id.setup_title)).getText().toString());Assert.assertFalse(a.findViewById(R.id.next_button).isEnabled());});SystemClock.sleep(180);picture("world171-large-mode-setup.jpg");}
  try(ActivityScenario<GameActivity> scene=ActivityScenario.launch(prepare(52,17152,1000,false,true))){MyGLSurfaceView[] gl={null};scene.onActivity(a->gl[0]=a.findViewById(R.id.mySurfaceView));long deadline=SystemClock.uptimeMillis()+18000;while(NativeInterface.playTimeMillis()==0&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(30);Assert.assertTrue(NativeInterface.playTimeMillis()>0);readyGL(gl[0],8);int began=NativeInterface.playTimeMillis();long wall=System.nanoTime();SystemClock.sleep(6000);int advanced=NativeInterface.playTimeMillis()-began;Debug.MemoryInfo memory=new Debug.MemoryInfo();Debug.getMemoryInfo(memory);Assert.assertTrue(advanced>0);picture("world171-large-live.jpg");write("world171-large-live.json",new JSONObject().put("status","PASS").put("normal_worker",true).put("sample_ns",System.nanoTime()-wall).put("simulation_progress_ms",advanced).put("pss_kib",memory.getTotalPss()).put("models",0).put("gl_completions_not_present_fps",true).put("physical_phone",false).put("human_play",false));}
 }
}
